import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { issueRtcToken } from '../server/voiceprint/rtc-token.mjs';
import { validateEnrollmentWav, createVoiceprintHttp } from '../server/voiceprint/http.mjs';
import { enrollmentWav, VoiceprintRecognition, CallRecognition } from '../ui/voiceprint-recognition.js';
import { loadVoiceprintConfig } from '../server/voiceprint/config.mjs';

// Fixed vector generated by the official Python AccessToken reference.
assert.equal(issueRtcToken({appId:'012345678901234567890123',appKey:'fixture-secret',roomId:'room',userId:'player',issuedAt:1700000000,ttl:3600,nonce:12345}),
  '001012345678901234567890123OgA5MAAAAPFTZRD/U2UEAHJvb20GAHBsYXllcgUAAAAQ/1NlAQAQ/1NlAgAQ/1NlAwAQ/1NlBAAQ/1NlIAB6IV4Kax3HpALyBsDsxLQ6INbWv1THlNbw/QbTQlImMA==');
const wav=Buffer.from(enrollmentWav([new ArrayBuffer(25*32000)]));
assert.equal(validateEnrollmentWav(wav),25);
assert.throws(()=>validateEnrollmentWav(wav.subarray(0,100)),/invalid/);
assert.throws(()=>validateEnrollmentWav(Buffer.from(enrollmentWav([new ArrayBuffer(32000)]))),/invalid_duration/);
const folder=await fs.mkdtemp(path.join(os.tmpdir(),'z-voiceprint-http-'));
try{
  await fs.writeFile(path.join(folder,'火山声纹配置.env'),'VOLC_RTC_APP_ID=fixture-app\nVOLC_RTC_APP_KEY=fixture-key\nVOLC_ACCESSKEY=fixture-ak\nVOLC_SECRETKEY=fixture-sk\nVOLC_ASR_API_KEY=fixture-asr\n');
  let called=0;
  const handler=createVoiceprintHttp(folder,{api:async(config,action,payload)=>{called++;assert.equal(action,'RegisterVoicePrint');assert.equal(payload.Version,2);assert.equal(payload.AudioFormat,0);return {status:200,data:{Result:'test-voiceprint'}};}});
  const request=origin=>new Request('http://localhost:1234/api/voiceprint/enroll',{method:'POST',headers:{Origin:origin,'Content-Type':'audio/wav'},body:wav});
  assert.equal((await handler(request('https://other.example'))).status,403);assert.equal(called,0);
  assert.equal((await handler(request('http://localhost:1234'))).status,200);assert.equal(called,1);
  const config=await loadVoiceprintConfig(folder,{});assert.equal(config.voiceprintId,'test-voiceprint');assert.deepEqual(config.missing,[]);
  assert.equal((await fs.stat(path.join(folder,'data/voiceprint/profile.json'))).mode&0o777,0o600);
  assert.deepEqual(await fs.readdir(path.join(folder,'data/voiceprint')),['profile.json'],'no enrollment recording retained');
  assert.equal((await handler(request('http://localhost:1234'))).status,200);assert.equal(called,1,'do not register duplicate profiles');
  assert.equal((await loadVoiceprintConfig(folder,{VOLC_RTC_APP_ID:'different-app'})).voiceprintId,'','profiles are scoped to their application');
}finally{await fs.rm(folder,{recursive:true,force:true});}

const settle=async()=>{for(let i=0;i<30;i++)await Promise.resolve();};
let automaticCapture=0,setupError;
const unconfiguredPlayer=new VoiceprintRecognition({mediaDevices:{async getUserMedia(){automaticCapture++;throw Error('unexpected capture');}}});
unconfiguredPlayer.onerror=e=>setupError=e.error;
unconfiguredPlayer.start({credentialsConfigured:true,needsEnrollment:true});await settle();
assert.equal(setupError,'voiceprint_setup_required');assert.equal(automaticCapture,0,'joining a call must never start enrollment recording');
let captures=0,stops=0,leaves=0,destroys=0,createdWith;
const engine={on(){},async setAudioCaptureConfig(c){assert.equal(c.noiseSuppression,false);assert.equal(c.autoGainControl,false);assert.equal(c.echoCancellation,true);},async joinRoom(){},async startAudioCapture(){captures++;},async stopAudioCapture(){stops++;},async leaveRoom(){leaves++;}};
const sdk={createEngine(appId){createdWith=appId;return engine;},destroyEngine(){destroys++;}};
class Socket{static last;constructor(){Socket.last=this;this.sent=[];}send(x){this.sent.push(JSON.parse(x));}close(){this.closed=true;}}
const recognition=new VoiceprintRecognition({loadSdk:async()=>({default:sdk}),WebSocketClass:Socket,location:{href:'http://localhost:1234/'}});
const transcripts=[];let started=0;recognition.onresult=e=>transcripts.push(e);recognition.onstart=()=>started++;
recognition.start({credentialsConfigured:true,needsEnrollment:false});await settle();
const socket=Socket.last;
socket.onmessage({data:JSON.stringify({type:'rtc',appId:'fixture-app',roomId:'room',userId:'player',token:'short-lived-token'})});await settle();
assert.equal(createdWith,'fixture-app');assert.deepEqual(socket.sent,[{type:'joined'}]);assert.equal(captures,0);
socket.onmessage({data:JSON.stringify({type:'ready'})});await settle();assert.equal(captures,1);assert.equal(started,1);
socket.onmessage({data:JSON.stringify({type:'transcript',conversationId:'a',text:'你好',final:false,speakerVerified:true})});await settle();
socket.onmessage({data:JSON.stringify({type:'transcript',conversationId:'a',text:'你好。',final:true,speakerVerified:true})});await settle();
assert.equal(transcripts.length,2);assert.equal(transcripts[1].turnFinal,true);assert(!socket.closed);
recognition.abort();await settle();assert(socket.closed);assert.equal(stops,1);assert.equal(leaves,1);assert.equal(destroys,1);

// A permission/capture result may arrive after the user has already hung up.
let resolveCapture,lateStops=0,lateStarts=0;
const lateEngine={on(){},async setAudioCaptureConfig(){},async joinRoom(){},startAudioCapture(){return new Promise(resolve=>{resolveCapture=resolve;});},async stopAudioCapture(){lateStops++;},async leaveRoom(){}};
const late=new VoiceprintRecognition({loadSdk:async()=>({default:{createEngine:()=>lateEngine,destroyEngine(){}}}),WebSocketClass:Socket,location:{href:'http://localhost:1234/'}});
late.onstart=()=>lateStarts++;late.start({credentialsConfigured:true,needsEnrollment:false});await settle();
const lateSocket=Socket.last;lateSocket.onmessage({data:JSON.stringify({type:'rtc',appId:'app',roomId:'room',userId:'p',token:'token'})});await settle();
lateSocket.onmessage({data:JSON.stringify({type:'ready'})});await settle();late.abort();resolveCapture();await settle();
assert.equal(lateStarts,0);assert(lateStops>=2,'late capture is stopped again after permission resolves');

let legacyStarts=0,protectedStarts=0;
class Legacy{start(){legacyStarts++;}abort(){}}
class Protected{start(){protectedStarts++;}abort(){}}
let wrapper=new CallRecognition({fetchImpl:async()=>Response.json({requested:true}),Legacy,Protected});wrapper.start();await settle();assert.equal(protectedStarts,1);assert.equal(legacyStarts,0);wrapper.abort();
wrapper=new CallRecognition({fetchImpl:async()=>Response.json({requested:false,invalidMode:true}),Legacy,Protected});let failed;wrapper.onerror=e=>failed=e.error;wrapper.start();await settle();assert.equal(legacyStarts,0);assert(failed);wrapper.abort();
console.log('PASS RTC reference token, enrollment WAV validation and application-scoped storage, protected browser capture, verified transcripts, cleanup and no implicit fallback');
